deep: [
{q: "Who is honoured as the father of English poetry?", a: "Geoffrey Chaucer", pool: "author", st: "Geoffrey Chaucer is honoured as the father of English poetry.", fact: "চসারই প্রথম ইংরেজিকে সাহিত্যের মর্যাদাপূর্ণ ভাষা করে তোলেন।", u: 0},
{q: "Who wrote the epic Paradise Lost?", a: "John Milton", pool: "author", st: "John Milton wrote the epic Paradise Lost.", fact: "অন্ধ অবস্থায় মিল্টন মুখে বলে এই মহাকাব্য লিখিয়েছিলেন।", u: 1},
{q: "Who wrote the mock epic The Rape of the Lock?", a: "Alexander Pope", pool: "author", st: "Alexander Pope wrote the mock epic The Rape of the Lock.", fact: "এক গোছা চুল কাটার তুচ্ছ ঘটনা নিয়ে লেখা এই ব্যঙ্গ মহাকাব্য।", u: 2},
{q: "Who is the senior partner behind Lyrical Ballads and its famous Preface?", a: "William Wordsworth", pool: "author", st: "William Wordsworth wrote the famous Preface to Lyrical Ballads.", fact: "মুখবন্ধে তিনি কবিতাকে শক্তিশালী অনুভূতির স্বতঃস্ফূর্ত উচ্ছ্বাস বলেছেন।", u: 3},
{q: "Who wrote A Tale of Two Cities, set in London and Paris?", a: "Charles Dickens", pool: "author", st: "Charles Dickens wrote A Tale of Two Cities.", fact: "ফরাসি বিপ্লবের পটভূমিতে লেখা এই উপন্যাস ডিকেন্সের ঐতিহাসিক রচনা।", u: 4},
{q: "Who wrote Mrs Dalloway, a novel covering a single day in London?", a: "Virginia Woolf", pool: "author", st: "Virginia Woolf wrote Mrs Dalloway.", fact: "এক দিনের গল্পে পুরো জীবনের স্মৃতি ঢেলে দেওয়াই এই উপন্যাসের কৌশল।", u: 5},
{q: "Who wrote Waiting for Godot, where nothing happens twice?", a: "Samuel Beckett", pool: "author", st: "Samuel Beckett wrote Waiting for Godot.", fact: "গোডো কখনো আসে না, অপেক্ষাটাই নাটকের পুরো বিষয়।", u: 5},
{q: "Who wrote The Canterbury Tales with its pilgrims telling stories?", a: "Geoffrey Chaucer", pool: "author", st: "Geoffrey Chaucer wrote The Canterbury Tales.", fact: "তীর্থযাত্রীদের গল্প বলার প্রতিযোগিতাই এই রচনার কাঠামো।", u: 0},
{q: "Who wrote Ulysses, set in Dublin on a single day?", a: "James Joyce", pool: "author", st: "James Joyce wrote Ulysses.", fact: "ইউলিসিস আধুনিক উপন্যাসের সবচেয়ে প্রভাবশালী পরীক্ষামূলক রচনা।", u: 5},
{q: "Who wrote The Waste Land, the defining poem of modern disillusion?", a: "T. S. Eliot", pool: "author", st: "T. S. Eliot wrote The Waste Land.", fact: "প্রথম বিশ্বযুদ্ধের পরের ভাঙা সভ্যতার ছবি এই কবিতার প্রাণ।", u: 5},
{q: "Who wrote The Castle of Otranto, the first Gothic novel?", a: "Horace Walpole", pool: "author", st: "Horace Walpole wrote The Castle of Otranto.", fact: "এই উপন্যাস থেকেই গথিক ধারার ভূতুড়ে দুর্গ আর রহস্যের চল শুরু।", u: 2},
{q: "The earliest surviving long epic in English comes from which period?", a: "Old English Period", pool: "period", st: "The earliest surviving long epic in English comes from the Old English Period.", fact: "Beowulf এর পাণ্ডুলিপি প্রায় হাজার বছরের পুরনো, টিকে থাকা সবচেয়ে প্রাচীন দীর্ঘ ইংরেজি কবিতা হিসেবেই এটি প্রাচীন যুগের প্রধান প্রমাণ।", u: 0},
{q: "Who first brought blank verse into English poetry?", a: "Earl of Surrey", pool: "author", st: "The Earl of Surrey first brought blank verse into English poetry.", fact: "সারে ভার্জিলের অনুবাদে প্রথম ছন্দমিলহীন পঙক্তি ব্যবহার করেন।", u: 1},
{q: "Who wrote Astrophel and Stella, the first great English sonnet sequence?", a: "Sir Philip Sidney", pool: "author", st: "Sir Philip Sidney wrote Astrophel and Stella.", fact: "সিডনির এই ধারাবাহিকের পরেই ইংল্যান্ডে সনেট লেখার জোয়ার আসে।", u: 1},
{q: "Who wrote The Flea, a witty metaphysical love poem?", a: "John Donne", pool: "author", st: "John Donne wrote The Flea, a witty metaphysical love poem.", fact: "ডান মেটাফিজিক্যাল কবিদের নেতা, যুক্তি দিয়ে প্রেম বোঝানো তাঁর ঢঙ।", u: 1},
{q: "Who wrote The Pilgrim's Progress, the great Puritan allegory?", a: "John Bunyan", pool: "author", st: "John Bunyan wrote The Pilgrim's Progress.", fact: "জেলে বসে লেখা এই রূপক কাহিনি ইংরেজি গদ্যের মাইলফলক।", u: 1},
{q: "Who wrote Gulliver's Travels, the sharpest satire on human pride?", a: "Jonathan Swift", pool: "author", st: "Jonathan Swift wrote Gulliver's Travels.", fact: "শিশুতোষ মনে হলেও বইটি আসলে মানুষের অহংকারের তীব্র ব্যঙ্গ।", u: 2},
{q: "Who wrote Frankenstein, the Gothic tale of a created monster?", a: "Mary Shelley", pool: "author", st: "Mary Shelley wrote Frankenstein.", fact: "মাত্র আঠারো বছর বয়সে মেরি শেলি এই উপন্যাসের খসড়া লেখেন।", u: 3}
]
